-- Real PostgreSQL source-bound authority, commitment and reload assertions.
-- Synthetic producer receipts deliberately exercise UTF8 commitment separately
-- from PostgreSQL projection codec; no actual runtime work is claimed here.
begin;
create function pg_temp.id(n integer) returns uuid language sql immutable as $$select ('99100700-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid$$;
create function pg_temp.ok(v boolean,m text) returns void language plpgsql as $$begin if v is distinct from true then raise exception 'ASSERTION: %',m;end if;end$$;
insert into auth.users(id,email) select pg_temp.id(n),'source-read-'||n||'@example.invalid' from generate_series(1,6)n;
insert into public.users(id,email,is_axiom_internal) select pg_temp.id(n),'source-read-'||n||'@example.invalid',n=4 from generate_series(1,6)n;
insert into public.tenants(id,slug,name) values(pg_temp.id(11),'source-read-a','A'),(pg_temp.id(12),'source-read-b','B');
insert into public.tenant_users(tenant_id,user_id,role) values(pg_temp.id(11),pg_temp.id(1),'owner'),(pg_temp.id(11),pg_temp.id(2),'admin'),(pg_temp.id(11),pg_temp.id(3),'viewer'),(pg_temp.id(11),pg_temp.id(4),'axiom_analyst'),(pg_temp.id(11),pg_temp.id(5),'axiom_analyst'),(pg_temp.id(12),pg_temp.id(1),'owner');
insert into public.estates(id,tenant_id,slug,name) values(pg_temp.id(21),pg_temp.id(11),'source-read-a','A'),(pg_temp.id(22),pg_temp.id(12),'source-read-b','B');
insert into public.control_libraries(version,published_at,published_by,change_log,control_count) values('source-read-test',now(),'test','Synthetic fixture',0);
insert into public.engagements(id,tenant_id,estate_id,library_version,title) values(pg_temp.id(31),pg_temp.id(11),null,'source-read-test','Unassigned A'),(pg_temp.id(32),pg_temp.id(12),null,'source-read-test','Unassigned B'),(pg_temp.id(33),pg_temp.id(11),pg_temp.id(21),'source-read-test','Assigned A');
create function pg_temp.metadata() returns jsonb language sql as $$select jsonb_build_object('version',1,'scope','static_html_form_descendants','sourceSha256',repeat('b',64),'observedFormCount',1,'formsTruncated',false,'forms',jsonb_build_array(jsonb_build_object('ordinal',1,'method','post','observedControlCount',3,'excludedControlCount',0,'controlsTruncated',false,'controls',jsonb_build_array('{"ordinal":1,"element":"input","inputType":"email","requiredAttribute":true,"disabledAttribute":false}'::jsonb,'{"ordinal":2,"element":"input","inputType":"text","requiredAttribute":false,"disabledAttribute":false}'::jsonb,'{"ordinal":3,"element":"input","inputType":"tel","requiredAttribute":false,"disabledAttribute":true}'::jsonb))))$$;
insert into public.public_website_checks(id,tenant_id,actor_id,correlation_id,requested_url,final_url,status,result) values(pg_temp.id(41),pg_temp.id(11),pg_temp.id(1),pg_temp.id(141),'https://example.invalid/','https://example.invalid/','checked',jsonb_build_object('requestedUrl','https://example.invalid/','finalUrl','https://example.invalid/','checkedAt',now(),'status','checked','httpStatus',200,'bytes',3,'contentSha256',repeat('a',64),'title','Never a private fact','headings','[]'::jsonb,'publicLinks','[]'::jsonb,'auditPages',jsonb_build_array(jsonb_build_object('kind','contact','status','checked','contentSha256',repeat('b',64),'formMetadata',pg_temp.metadata()),jsonb_build_object('kind','privacy','status','unavailable'))));
create function pg_temp.bind() returns uuid language plpgsql as $$declare v jsonb;r jsonb;prior text:=current_user;begin set local role human_action_writer;v:=public.get_public_source_projection(pg_temp.id(11),pg_temp.id(1),pg_temp.id(31),pg_temp.id(41));r:=public.record_public_source_binding(pg_temp.id(11),pg_temp.id(1),pg_temp.id(31),pg_temp.id(41),v->'runtime_binding'->>'root_content_sha256',v->'runtime_binding'->>'projection_sha256',pg_temp.id(101));execute format('set local role %I',prior);return (r->>'binding_id')::uuid;exception when others then execute format('set local role %I',prior);raise;end$$;
create temporary table source_fixture(k text primary key,v jsonb);
grant select on source_fixture to human_action_writer,agent_ledger_writer,service_role;
insert into source_fixture values('binding',to_jsonb(pg_temp.bind()));
create function pg_temp.binding() returns uuid language sql as $$select (v#>>'{}')::uuid from source_fixture where k='binding'$$;
create function pg_temp.load(o jsonb default '{}') returns jsonb language plpgsql as $$declare r jsonb;prior text:=current_user;begin set local role human_action_writer;r:=public.get_public_source_agent_input(coalesce((o->>'tenant')::uuid,pg_temp.id(11)),coalesce((o->>'actor')::uuid,pg_temp.id(1)),coalesce((o->>'engagement')::uuid,pg_temp.id(31)),coalesce((o->>'binding')::uuid,pg_temp.binding()),coalesce(o->>'agent','drishti'),(o->>'observation')::uuid);execute format('set local role %I',prior);return r;exception when others then execute format('set local role %I',prior);raise;end$$;

create function pg_temp.start(o jsonb default '{}') returns uuid language plpgsql as $$declare r jsonb;v jsonb;prior text:=current_user;begin v:=pg_temp.load(o);set local role human_action_writer;r:=public.record_generic_agent_run_start(coalesce((o->>'tenant')::uuid,pg_temp.id(11)),coalesce((o->>'actor')::uuid,pg_temp.id(1)),coalesce(o->>'agent','drishti'),coalesce((o->>'engagement')::uuid,pg_temp.id(31)),coalesce((o->>'correlation')::uuid,gen_random_uuid()),coalesce(o->>'hash',encode(sha256(convert_to((v->'input')::text,'UTF8')),'hex')));execute format('set local role %I',prior);return (r->>'run_id')::uuid;exception when others then execute format('set local role %I',prior);raise;end$$;
create function pg_temp.dispatch(rid uuid,o jsonb default '{}') returns jsonb language plpgsql as $$declare r jsonb;v jsonb;prior text:=current_user;begin v:=pg_temp.load(o);set local role human_action_writer;r:=public.record_public_source_dispatch(coalesce((o->>'tenant')::uuid,pg_temp.id(11)),coalesce((o->>'actor')::uuid,pg_temp.id(1)),coalesce((o->>'engagement')::uuid,pg_temp.id(31)),coalesce((o->>'binding')::uuid,pg_temp.binding()),coalesce(o->>'agent','drishti'),(o->>'observation')::uuid,rid,coalesce(o->'input',v->'input'),coalesce(o->>'bytes',(v->'input')::text));execute format('set local role %I',prior);return r;exception when others then execute format('set local role %I',prior);raise;end$$;
create function pg_temp.runtime(rid uuid,o jsonb default '{}') returns jsonb language plpgsql as $$declare r jsonb;c uuid;prior text:=current_user;begin select correlation_id into c from public.agent_runs where id=rid;set local role agent_ledger_writer;r:=public.get_public_source_dispatch_input(coalesce((o->>'tenant')::uuid,pg_temp.id(11)),rid,coalesce(o->>'agent','drishti'),coalesce((o->>'correlation')::uuid,c));execute format('set local role %I',prior);return r;exception when others then execute format('set local role %I',prior);raise;end$$;
create function pg_temp.claim(rid uuid,o jsonb default '{}') returns jsonb language plpgsql as $$declare r jsonb;d public.public_source_dispatches;c uuid;prior text:=current_user;begin select * into d from public.public_source_dispatches where run_id=rid;select correlation_id into c from public.agent_runs where id=rid;set local role agent_ledger_writer;r:=public.claim_public_source_dispatch(coalesce((o->>'tenant')::uuid,pg_temp.id(11)),rid,coalesce(o->>'agent',d.agent),coalesce((o->>'correlation')::uuid,c),coalesce((o->>'dispatch')::uuid,d.id),coalesce(o->>'hash',d.request_hash));execute format('set local role %I',prior);return r;exception when others then execute format('set local role %I',prior);raise;end$$;
create function pg_temp.expected(input jsonb,agent text) returns jsonb language plpgsql as $$declare source jsonb;begin
if agent='drishti' then source:=input->'source';return jsonb_build_object('mode','public_website','observation',jsonb_build_object('version',1,'binding',source->'binding','pages',jsonb_build_array(source->'pages'->0||'{"form_state":"unexamined"}',source->'pages'->1||'{"form_state":"observed"}',source->'pages'->2||'{"form_state":"unavailable"}'),'private_facts','{"hosting_region":"unknown","backend_personal_data":"unknown","cross_border_processing":"unknown"}'::jsonb,'requires_human_review',true));end if;
return jsonb_build_object('mode','public_website','source_binding',input->'source_binding','private_facts','{"hosting_region":"unknown","backend_personal_data":"unknown","cross_border_processing":"unknown"}'::jsonb,'scope_limited',true,'unexamined_pages','["root"]'::jsonb,'unavailable_pages','["privacy"]'::jsonb,'indicators',jsonb_build_array(jsonb_build_object('page','contact','content_sha256',repeat('b',64),'form_ordinal',1,'control_ordinal',1,'input_type','email','indicator','potential_contact_collection','requires_human_review',true),jsonb_build_object('page','contact','content_sha256',repeat('b',64),'form_ordinal',1,'control_ordinal',3,'input_type','tel','indicator','potential_contact_collection','requires_human_review',true)));
end$$;
create function pg_temp.complete(rid uuid,output jsonb,bytes text default null,o jsonb default '{}') returns jsonb language plpgsql as $$declare r public.agent_runs;sid bigint;eid bigint;result jsonb;prior text:=current_user;action public.ledger_action_type;digest text;begin select * into strict r from public.agent_runs where id=rid;action:=(case r.agent when 'drishti' then 'discovery.started' else 'classification.started' end)::public.ledger_action_type;digest:=encode(sha256(convert_to(coalesce(bytes,output::text),'UTF8')),'hex');set local role agent_ledger_writer;
sid:=public.append_agent_ledger(r.tenant_id,r.correlation_id,'agent',r.agent,'1.0.0',null,null,action,r.engagement_id::text,r.input_redacted_hash,null,null,null,null,null,'pending',jsonb_build_object('phase','started','run_id',r.id,'request_hash',r.input_redacted_hash));
eid:=public.append_agent_ledger(r.tenant_id,r.correlation_id,'agent',r.agent,'1.0.0',null,null,action,r.engagement_id::text,r.input_redacted_hash,digest,null,null,null,null,'success',jsonb_build_object('phase','completed','run_id',r.id,'request_hash',r.input_redacted_hash,'started_entry',sid::text));
set local role human_action_writer;result:=public.record_generic_agent_run_finish(r.tenant_id,pg_temp.id(1),r.id,r.agent,r.engagement_id,r.correlation_id,r.input_redacted_hash,'succeeded',null,1,0,0,0,sid::text,eid::text,coalesce(o->>'response_hash',digest));execute format('set local role %I',prior);return result;exception when others then execute format('set local role %I',prior);raise;end$$;
create function pg_temp.observe(rid uuid,output jsonb,bytes text default null,o jsonb default '{}') returns jsonb language plpgsql as $$declare r jsonb;prior text:=current_user;begin set local role human_action_writer;r:=public.record_public_source_observation(coalesce((o->>'tenant')::uuid,pg_temp.id(11)),coalesce((o->>'actor')::uuid,pg_temp.id(1)),rid,output,coalesce(bytes,output::text));execute format('set local role %I',prior);return r;exception when others then execute format('set local role %I',prior);raise;end$$;
create function pg_temp.read(oid uuid,o jsonb default '{}') returns jsonb language plpgsql as $$declare r jsonb;prior text:=current_user;begin set local role service_role;r:=public.get_public_source_observation(coalesce((o->>'tenant')::uuid,pg_temp.id(11)),coalesce((o->>'actor')::uuid,pg_temp.id(3)),coalesce((o->>'engagement')::uuid,pg_temp.id(31)),oid);execute format('set local role %I',prior);return r;exception when others then execute format('set local role %I',prior);raise;end$$;

create function pg_temp.choices(o jsonb default '{}') returns jsonb language plpgsql as $$declare r jsonb;prior text:=current_user;begin set local role human_action_writer;r:=public.list_public_source_engagements(coalesce((o->>'tenant')::uuid,pg_temp.id(11)),coalesce((o->>'actor')::uuid,pg_temp.id(3)),coalesce((o->>'limit')::int,20),(o->>'created_at')::timestamptz,(o->>'id')::uuid);execute format('set local role %I',prior);return r;exception when others then execute format('set local role %I',prior);raise;end$$;
create function pg_temp.history(o jsonb default '{}') returns jsonb language plpgsql as $$declare r jsonb;prior text:=current_user;begin set local role human_action_writer;r:=public.list_public_source_observations(coalesce((o->>'tenant')::uuid,pg_temp.id(11)),coalesce((o->>'actor')::uuid,pg_temp.id(3)),coalesce((o->>'engagement')::uuid,pg_temp.id(31)),coalesce((o->>'binding')::uuid,pg_temp.binding()),coalesce((o->>'limit')::int,20),(o->>'created_at')::timestamptz,(o->>'id')::uuid);execute format('set local role %I',prior);return r;exception when others then execute format('set local role %I',prior);raise;end$$;
create function pg_temp.reconcile(rid uuid,o jsonb default '{}') returns jsonb language plpgsql as $$declare r jsonb;run public.agent_runs;prior text:=current_user;begin select * into run from public.agent_runs where id=rid;set local role human_action_writer;r:=public.reconcile_public_source_request(coalesce((o->>'tenant')::uuid,pg_temp.id(11)),coalesce((o->>'actor')::uuid,pg_temp.id(1)),coalesce((o->>'engagement')::uuid,pg_temp.id(31)),coalesce((o->>'binding')::uuid,pg_temp.binding()),coalesce(o->>'agent',run.agent,'drishti'),coalesce((o->>'correlation')::uuid,run.correlation_id,pg_temp.id(900)));execute format('set local role %I',prior);return r;exception when others then execute format('set local role %I',prior);raise;end$$;
-- Every new RPC is restricted read authority, never runtime writer access.
do $$declare signature text;r text;begin
for signature in select p.oid::regprocedure::text from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname in('list_public_source_engagements','list_public_source_observations','reconcile_public_source_request') loop
perform pg_temp.ok(has_function_privilege('human_action_writer',signature,'EXECUTE'),'human read access');
foreach r in array array['anon','authenticated','service_role','agent_ledger_writer','evidence_ingestion_writer'] loop perform pg_temp.ok(not has_function_privilege(r,signature,'EXECUTE'),'restricted read credential '||r);end loop;end loop;
for signature in select p.oid::regprocedure::text from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname in('public_source_read_member','public_source_observation_metadata') loop foreach r in array array['anon','authenticated','service_role','human_action_writer','agent_ledger_writer'] loop perform pg_temp.ok(not has_function_privilege(r,signature,'EXECUTE'),'private helper '||signature||r);end loop;end loop;
end$$;
select pg_temp.ok(jsonb_array_length(pg_temp.choices()->'data')=2,'only actual tenant choices');
select pg_temp.ok(pg_temp.choices(jsonb_build_object('actor',pg_temp.id(4)))->'data' is not null,'internal analyst choices without evidence-record capability');
select pg_temp.ok(pg_temp.choices(jsonb_build_object('actor',pg_temp.id(5)))->>'error'='forbidden','false internal role refused');
select pg_temp.ok(pg_temp.choices(jsonb_build_object('tenant',pg_temp.id(12)))->>'error'='forbidden','foreign member choices');
select pg_temp.ok(pg_temp.choices('{"limit":51}')->>'error'='invalid_record','bounded limit');
select pg_temp.ok(pg_temp.choices(jsonb_build_object('id',pg_temp.id(31)))->>'error'='invalid_record','incomplete cursor');
insert into public.tenant_users(tenant_id,user_id,role) values(pg_temp.id(11),pg_temp.id(6),'agent');
select pg_temp.ok(pg_temp.choices(jsonb_build_object('actor',pg_temp.id(6)))->>'error'='forbidden','agent cannot read human choices');
-- Same timestamp uses descending UUID tie-break; NULL estates are explicit.
update public.engagements set created_at='2026-10-01T12:00:00.123456Z' where tenant_id=pg_temp.id(11);
select pg_temp.ok(pg_temp.choices('{"limit":1}')->'data'->0->>'id'=pg_temp.id(33)::text,'newest tuple tie-break');
select pg_temp.ok(pg_temp.choices('{"limit":1}')->'has_more'='true'::jsonb,'bounded next page');
select pg_temp.ok(pg_temp.choices(pg_temp.choices('{"limit":1}')->'next_cursor')->'data'->0->>'id'=pg_temp.id(31)::text,'cursor moves older');
select pg_temp.ok(pg_temp.choices(pg_temp.choices('{"limit":1}')->'next_cursor')->'data'->0->'estate'='null'::jsonb,'unassigned estate preserved');
update public.engagements set status='cancelled' where id=pg_temp.id(33);
select pg_temp.ok(jsonb_array_length(pg_temp.choices()->'data')=1,'cancelled excluded');
update public.engagements set status='intake' where id=pg_temp.id(33);
select pg_temp.ok(jsonb_array_length(pg_temp.history()->'data')=0,'empty retained history explicit');
select pg_temp.ok(pg_temp.history(jsonb_build_object('engagement',pg_temp.id(32)))->>'error'='context_refused','foreign context refused');
select pg_temp.ok(pg_temp.history(jsonb_build_object('binding',pg_temp.id(999)))->>'error'='source_refused','unknown binding refused');
select pg_temp.ok(pg_temp.reconcile(null)->'outcome'->>'state'='not_found','no recorded own request');
-- Prepare a valid human request. Rows without actual source/claim proof are unknown.
create function pg_temp.state(rid uuid) returns text language sql as $$select pg_temp.reconcile(rid)->'outcome'->>'state'$$;
do $$declare rid uuid;r jsonb;out jsonb;oid uuid;begin
rid:=pg_temp.start();perform pg_temp.ok(pg_temp.state(rid)='unknown','generic row alone unknown');
r:=pg_temp.dispatch(rid);perform pg_temp.ok(pg_temp.state(rid)='unknown','unclaimed source request unknown');
r:=pg_temp.claim(rid);perform pg_temp.ok(pg_temp.state(rid)='running','actual recorded running claim');
perform pg_temp.ok(pg_temp.reconcile(rid,jsonb_build_object('actor',pg_temp.id(2)))->'outcome'->>'state'='not_found','different actor cannot reconcile request');
perform pg_temp.ok(pg_temp.reconcile(rid,jsonb_build_object('agent','vibhaag'))->'outcome'->>'state'='not_found','different agent scope');
perform pg_temp.ok(pg_temp.reconcile(rid,jsonb_build_object('engagement',pg_temp.id(33)))->>'error'='source_refused','wrong request engagement');
out:=pg_temp.expected(pg_temp.load()->'input','drishti');r:=pg_temp.complete(rid,out);
perform pg_temp.ok(pg_temp.state(rid)='completed_without_observation','confirmed completion is not retained output');
r:=pg_temp.observe(rid,out);oid:=(r->>'observation_id')::uuid;
perform pg_temp.ok(pg_temp.state(rid)='retained','actual immutable observation retained');
perform pg_temp.ok(pg_temp.reconcile(rid)->'outcome'->'observation'->>'observation_id'=oid::text,'recover actual observation ID');
perform pg_temp.ok(pg_temp.history()->'data'->0->>'observation_id'=oid::text,'viewer retained metadata reload');
perform pg_temp.ok(not pg_temp.history()->'data'->0?'output','metadata does not invent payload');
insert into source_fixture values('retained_run',to_jsonb(rid));
end$$;
-- Missing/contradictory commitments remain unknown, even a succeeded status.
do $$declare rid uuid;r jsonb;out jsonb;begin
out:=pg_temp.expected(pg_temp.load()->'input','drishti');rid:=pg_temp.start();r:=pg_temp.dispatch(rid);r:=pg_temp.claim(rid);r:=pg_temp.complete(rid,out,null,jsonb_build_object('response_hash',repeat('f',64)));perform pg_temp.ok(pg_temp.state(rid)='unknown','wrong response commitment unknown');
rid:=pg_temp.start();r:=pg_temp.dispatch(rid);r:=pg_temp.claim(rid);update public.agent_runs set metadata=jsonb_set(metadata,'{request_receipt}',to_jsonb('9999999'::text)) where id=rid;perform pg_temp.ok(pg_temp.state(rid)='unknown','missing request receipt unknown');
end$$;
-- A trusted controller's known runtime failure is distinct from a lost transport.
create function pg_temp.fail(rid uuid,reported boolean) returns jsonb language plpgsql as $$declare r public.agent_runs;out jsonb;prior text:=current_user;begin select * into r from public.agent_runs where id=rid;set local role human_action_writer;out:=public.record_generic_agent_run_finish(r.tenant_id,pg_temp.id(1),r.id,r.agent,r.engagement_id,r.correlation_id,r.input_redacted_hash,'failed',case when reported then 'agent_reported_failure' else 'agent_invocation_failed' end,1,0,0,0,null,null,null);execute format('set local role %I',prior);return out;exception when others then execute format('set local role %I',prior);raise;end$$;
do $$declare rid uuid;r jsonb;begin rid:=pg_temp.start();r:=pg_temp.dispatch(rid);r:=pg_temp.claim(rid);r:=pg_temp.fail(rid,true);perform pg_temp.ok(pg_temp.state(rid)='confirmed_failed','confirmed runtime reported failure');rid:=pg_temp.start();r:=pg_temp.dispatch(rid);r:=pg_temp.claim(rid);r:=pg_temp.fail(rid,false);perform pg_temp.ok(pg_temp.state(rid)='unknown','ambiguous transport never false failed');end$$;
-- Complete another observation, including same-time keyset pagination.
do $$declare rid uuid;r jsonb;out jsonb;a public.public_source_observations;v jsonb;begin
out:=pg_temp.expected(pg_temp.load()->'input','drishti');rid:=pg_temp.start();r:=pg_temp.dispatch(rid);r:=pg_temp.claim(rid);r:=pg_temp.complete(rid,out);r:=pg_temp.observe(rid,out);
v:=pg_temp.history('{"limit":1}');perform pg_temp.ok(v->'has_more'='true'::jsonb,'history has older page');
perform pg_temp.ok(jsonb_array_length(pg_temp.history(v->'next_cursor')->'data')=1,'history older page without duplicates');
perform pg_temp.ok(pg_temp.history(v->'next_cursor')->'data'->0->>'observation_id'<>v->'data'->0->>'observation_id','strict tuple cursor');
end$$;
-- A runtime completion awaiting generic confirmation is unknown, never
-- advertised as live execution or a retained business result.
do $$declare rid uuid;r jsonb;out jsonb;begin out:=pg_temp.expected(pg_temp.load()->'input','drishti');rid:=pg_temp.start();r:=pg_temp.dispatch(rid);r:=pg_temp.claim(rid);r:=pg_temp.complete(rid,out);update public.agent_runs set status='running',completed_at=null,metadata=metadata-array['settlement','settlement_receipt','runtime_outcome','runtime_normalized_input_hash','runtime_output_hash','response_output_hash'] where id=rid;perform pg_temp.ok(pg_temp.state(rid)='unknown','durable completion contradicts live running');end$$;
-- Existing immutable output does not override contradictory run commitments.
do $$declare rid uuid;original jsonb;begin rid:=(select (v#>>'{}')::uuid from source_fixture where k='retained_run');select metadata into original from public.agent_runs where id=rid;update public.agent_runs set metadata=jsonb_set(metadata,'{runtime_output_hash}',to_jsonb(repeat('f',64))) where id=rid;perform pg_temp.ok(pg_temp.state(rid)='unknown','retained row cannot override bad runtime commitment');update public.agent_runs set metadata=original where id=rid;end$$;
-- Reconciliation reads must not append ledger entries, claim or change runs.
create temporary table read_counts as select (select count(*) from public.audit_ledger) ledger,(select count(*) from public.agent_runs) runs,(select count(*) from public.public_source_dispatch_claims) claims,(select count(*) from public.public_source_observations) observations;
select pg_temp.choices();select pg_temp.history();select pg_temp.reconcile((select (v#>>'{}')::uuid from source_fixture where k='retained_run'));
select pg_temp.ok((select ledger=(select count(*) from public.audit_ledger) and runs=(select count(*) from public.agent_runs) and claims=(select count(*) from public.public_source_dispatch_claims) and observations=(select count(*) from public.public_source_observations) from read_counts),'reads have zero mutation');
-- Membership/internal flags and current context are checked afresh.
delete from public.tenant_users where tenant_id=pg_temp.id(11) and user_id=pg_temp.id(3);
select pg_temp.ok(pg_temp.history()->>'error'='forbidden','revoked viewer read');
update public.users set is_axiom_internal=false where id=pg_temp.id(4);
select pg_temp.ok(pg_temp.choices(jsonb_build_object('actor',pg_temp.id(4)))->>'error'='forbidden','revoked internal flag choices');
update public.engagements set status='cancelled' where id=pg_temp.id(31);
select pg_temp.ok(pg_temp.reconcile((select (v#>>'{}')::uuid from source_fixture where k='retained_run'))->>'error'='context_refused','cancelled request context');
select pg_temp.ok(not exists(select 1 from public.verify_ledger(pg_temp.id(11))),'ledger chain unchanged');
rollback;
